/*
 * Legacy Vietnamese schema retained for design reference only.
 * The executable PostgreSQL schema used by the application starts below.
 *
CREATE TABLE "HangHangKhong" (
  "MaHang" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TenHang" VARCHAR(150) NOT NULL,
  "MaIATA" VARCHAR(10) UNIQUE,
  "QuocGia" VARCHAR(100),
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "SanBay" (
  "MaSanBay" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TenSanBay" VARCHAR(200) NOT NULL,
  "MaIATA" VARCHAR(10) UNIQUE,
  "ThanhPho" VARCHAR(100),
  "QuocGia" VARCHAR(100),
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "MayBay" (
  "MaMayBay" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "SoHieu" VARCHAR(50) UNIQUE NOT NULL,
  "LoaiMayBay" VARCHAR(100),
  "SoGhe" INT NOT NULL CHECK ("SoGhe" > 0),
  "MaHang" INT NOT NULL,
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "ChuyenBay" (
  "MaChuyenBay" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "SoHieuChuyenBay" VARCHAR(20) NOT NULL UNIQUE,
  "MaMayBay" INT NOT NULL,
  "SanBayDi" INT NOT NULL,
  "SanBayDen" INT NOT NULL,
  "ThoiGianKhoiHanh" TIMESTAMP NOT NULL,
  "ThoiGianDen" TIMESTAMP,
  "TrangThai" VARCHAR(50) NOT NULL DEFAULT 'SCHEDULED',
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "chk_chuyen_bay_san_bay" CHECK ("SanBayDi" <> "SanBayDen"),
  CONSTRAINT "chk_chuyen_bay_thoi_gian" CHECK ("ThoiGianDen" IS NULL OR "ThoiGianDen" > "ThoiGianKhoiHanh")
);

CREATE TABLE "HangGhe" (
  "MaHangGhe" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TenHangGhe" VARCHAR(50) NOT NULL UNIQUE,
  "MoTa" VARCHAR(300)
);

CREATE TABLE "GiaVe" (
  "MaGiaVe" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "MaChuyenBay" INT NOT NULL,
  "MaHangGhe" INT NOT NULL,
  "Gia" NUMERIC(18,2) NOT NULL CHECK ("Gia" >= 0),
  "SoLuongVe" INT NOT NULL CHECK ("SoLuongVe" >= 0),
  CONSTRAINT "uq_giave_chuyenbay_hangghe" UNIQUE ("MaChuyenBay", "MaHangGhe")
);

CREATE TABLE "KhachHang" (
  "MaKhachHang" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "HoTen" VARCHAR(150) NOT NULL,
  "NgaySinh" DATE,
  "GioiTinh" VARCHAR(20),
  "CCCD" VARCHAR(20) UNIQUE,
  "HoChieu" VARCHAR(30) UNIQUE,
  "SoDienThoai" VARCHAR(15) UNIQUE,
  "Email" VARCHAR(150) UNIQUE,
  "DiaChi" VARCHAR(250),
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "DatVe" (
  "MaDatVe" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "MaKhachHang" INT NOT NULL,
  "MaChuyenBay" INT NOT NULL,
  "MaHangGhe" INT NOT NULL,
  "NgayDat" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "SoLuong" INT NOT NULL DEFAULT 1 CHECK ("SoLuong" > 0),
  "TongTien" NUMERIC(18,2) NOT NULL CHECK ("TongTien" >= 0),
  "TrangThai" VARCHAR(50) NOT NULL DEFAULT 'PENDING',
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "chk_datve_trangthai" CHECK ("TrangThai" IN ('PENDING', 'PAID', 'CANCELLED'))
);

CREATE TABLE "VeMayBay" (
  "MaVe" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "MaDatVe" INT NOT NULL,
  "MaKhachHang" INT NOT NULL,
  "SoGhe" VARCHAR(10),
  "MaVeDienTu" VARCHAR(100) UNIQUE,
  "TrangThai" VARCHAR(50) NOT NULL DEFAULT 'ISSUED',
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "chk_ve_trangthai" CHECK ("TrangThai" IN ('ISSUED', 'USED', 'VOID'))
);

CREATE TABLE "ThanhToan" (
  "MaThanhToan" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "MaDatVe" INT NOT NULL,
  "NgayThanhToan" TIMESTAMP,
  "SoTien" NUMERIC(18,2) NOT NULL CHECK ("SoTien" >= 0),
  "PhuongThuc" VARCHAR(50),
  "TrangThai" VARCHAR(50) NOT NULL DEFAULT 'PENDING',
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "chk_thanhtoan_trangthai" CHECK ("TrangThai" IN ('PENDING', 'SUCCESS', 'FAILED'))
);

CREATE TABLE "TaiKhoan" (
  "MaTaiKhoan" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "MaKhachHang" INT,
  "TenDangNhap" VARCHAR(100) UNIQUE NOT NULL,
  "MatKhau" VARCHAR(255) NOT NULL,
  "VaiTro" VARCHAR(50) NOT NULL DEFAULT 'USER',
  "TrangThai" VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "chk_taikhoan_vaitro" CHECK ("VaiTro" IN ('ADMIN', 'STAFF', 'USER')),
  CONSTRAINT "chk_taikhoan_trangthai" CHECK ("TrangThai" IN ('ACTIVE', 'LOCKED', 'DELETED'))
);

ALTER TABLE "MayBay"
  ADD CONSTRAINT "fk_maybay_hanghangkhong"
