-- Flight Ticket Management System - PostgreSQL 16
-- Single executable source for schema initialization and reference seed data.

BEGIN;

CREATE TABLE IF NOT EXISTS airlines (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(150) NOT NULL,
    iata_code VARCHAR(3) NOT NULL UNIQUE,
    country VARCHAR(100),
    cabin_baggage_kg INTEGER NOT NULL DEFAULT 7 CHECK (cabin_baggage_kg BETWEEN 0 AND 30),
    included_checked_baggage_kg INTEGER NOT NULL DEFAULT 0 CHECK (included_checked_baggage_kg BETWEEN 0 AND 100),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_airlines_iata_code CHECK (iata_code = UPPER(iata_code))
);

ALTER TABLE airlines ADD COLUMN IF NOT EXISTS cabin_baggage_kg INTEGER NOT NULL DEFAULT 7;
ALTER TABLE airlines ADD COLUMN IF NOT EXISTS included_checked_baggage_kg INTEGER NOT NULL DEFAULT 0;

CREATE TABLE IF NOT EXISTS baggage_options (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    airline_id BIGINT NOT NULL REFERENCES airlines(id) ON UPDATE CASCADE ON DELETE RESTRICT,
    weight_kg INTEGER NOT NULL CHECK (weight_kg BETWEEN 1 AND 100),
    price NUMERIC(18, 2) NOT NULL CHECK (price >= 0),
    active BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT uq_baggage_options_airline_weight UNIQUE (airline_id, weight_kg)
);

CREATE TABLE IF NOT EXISTS airports (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(200) NOT NULL,
    iata_code VARCHAR(3) NOT NULL UNIQUE,
    city VARCHAR(100) NOT NULL,
    country VARCHAR(100) NOT NULL,
    timezone VARCHAR(50) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_airports_iata_code CHECK (iata_code = UPPER(iata_code))
);

CREATE TABLE IF NOT EXISTS aircraft (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    registration_number VARCHAR(20) NOT NULL UNIQUE,
    model VARCHAR(100) NOT NULL,
    seat_capacity INTEGER NOT NULL CHECK (seat_capacity > 0),
    airline_id BIGINT NOT NULL REFERENCES airlines(id) ON UPDATE CASCADE ON DELETE RESTRICT,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS flights (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    flight_number VARCHAR(20) NOT NULL,
    aircraft_id BIGINT NOT NULL REFERENCES aircraft(id) ON UPDATE CASCADE ON DELETE RESTRICT,
    departure_airport_id BIGINT NOT NULL REFERENCES airports(id) ON UPDATE CASCADE ON DELETE RESTRICT,
    arrival_airport_id BIGINT NOT NULL REFERENCES airports(id) ON UPDATE CASCADE ON DELETE RESTRICT,
    departure_time TIMESTAMP WITH TIME ZONE NOT NULL,
    arrival_time TIMESTAMP WITH TIME ZONE NOT NULL,
    status VARCHAR(30) NOT NULL DEFAULT 'SCHEDULED',
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_flights_number_departure UNIQUE (flight_number, departure_time),
    CONSTRAINT chk_flights_airports CHECK (departure_airport_id <> arrival_airport_id),
    CONSTRAINT chk_flights_time CHECK (arrival_time > departure_time),
    CONSTRAINT chk_flights_status CHECK (status IN ('SCHEDULED', 'BOARDING', 'DEPARTED', 'ARRIVED', 'CANCELLED', 'DELAYED'))
);

CREATE TABLE IF NOT EXISTS fare_classes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(20) NOT NULL UNIQUE,
    name VARCHAR(50) NOT NULL UNIQUE,
    description VARCHAR(300)
);

CREATE TABLE IF NOT EXISTS flight_fares (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    flight_id BIGINT NOT NULL REFERENCES flights(id) ON UPDATE CASCADE ON DELETE CASCADE,
    fare_class_id BIGINT NOT NULL REFERENCES fare_classes(id) ON UPDATE CASCADE ON DELETE RESTRICT,
    price NUMERIC(18, 2) NOT NULL CHECK (price >= 0),
    seat_quota INTEGER NOT NULL CHECK (seat_quota >= 0),
    available_seats INTEGER NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT uq_flight_fares_flight_class UNIQUE (flight_id, fare_class_id),
    CONSTRAINT chk_flight_fares_available CHECK (available_seats BETWEEN 0 AND seat_quota)
);

CREATE TABLE IF NOT EXISTS customers (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name VARCHAR(150) NOT NULL,
    date_of_birth DATE,
    gender VARCHAR(20),
    citizen_id VARCHAR(20) UNIQUE,
    passport_number VARCHAR(30) UNIQUE,
    phone VARCHAR(20) UNIQUE,
    email VARCHAR(150) UNIQUE,
    address VARCHAR(250),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS accounts (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id BIGINT UNIQUE REFERENCES customers(id) ON UPDATE CASCADE ON DELETE SET NULL,
    username VARCHAR(100) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    role VARCHAR(20) NOT NULL DEFAULT 'USER',
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_accounts_role CHECK (role IN ('ADMIN', 'STAFF', 'USER')),
    CONSTRAINT chk_accounts_status CHECK (status IN ('ACTIVE', 'LOCKED', 'DELETED'))
);

CREATE TABLE IF NOT EXISTS bookings (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_code VARCHAR(12) NOT NULL UNIQUE,
    customer_id BIGINT NOT NULL REFERENCES customers(id) ON UPDATE CASCADE ON DELETE RESTRICT,
    flight_id BIGINT NOT NULL REFERENCES flights(id) ON UPDATE CASCADE ON DELETE RESTRICT,
    fare_class_id BIGINT NOT NULL REFERENCES fare_classes(id) ON UPDATE CASCADE ON DELETE RESTRICT,
    booked_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    passenger_count INTEGER NOT NULL DEFAULT 1 CHECK (passenger_count > 0),
    total_amount NUMERIC(18, 2) NOT NULL CHECK (total_amount >= 0),
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    expires_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_bookings_status CHECK (status IN ('PENDING', 'PAID', 'REFUND_REQUESTED', 'REFUNDED', 'CANCELLED', 'EXPIRED'))
);

CREATE TABLE IF NOT EXISTS booking_passengers (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_id BIGINT NOT NULL REFERENCES bookings(id) ON UPDATE CASCADE ON DELETE CASCADE,
    full_name VARCHAR(150) NOT NULL,
    document_number VARCHAR(30),
    seat_number VARCHAR(10),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE booking_passengers ADD COLUMN IF NOT EXISTS seat_number VARCHAR(10);
ALTER TABLE booking_passengers ADD COLUMN IF NOT EXISTS checked_baggage_kg INTEGER NOT NULL DEFAULT 0;
ALTER TABLE booking_passengers ADD COLUMN IF NOT EXISTS baggage_price NUMERIC(18, 2) NOT NULL DEFAULT 0;

CREATE TABLE IF NOT EXISTS tickets (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_id BIGINT NOT NULL REFERENCES bookings(id) ON UPDATE CASCADE ON DELETE CASCADE,
    passenger_name VARCHAR(150) NOT NULL,
    passenger_document VARCHAR(30),
    seat_number VARCHAR(10),
    electronic_ticket_code VARCHAR(100) NOT NULL UNIQUE,
    status VARCHAR(20) NOT NULL DEFAULT 'ISSUED',
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_tickets_booking_seat UNIQUE (booking_id, seat_number),
    CONSTRAINT chk_tickets_status CHECK (status IN ('ISSUED', 'USED', 'VOID'))
);

CREATE TABLE IF NOT EXISTS payments (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_id BIGINT NOT NULL REFERENCES bookings(id) ON UPDATE CASCADE ON DELETE CASCADE,
    transaction_code VARCHAR(100) UNIQUE,
    paid_at TIMESTAMP WITH TIME ZONE,
    amount NUMERIC(18, 2) NOT NULL CHECK (amount >= 0),
    method VARCHAR(30) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_payments_method CHECK (method IN ('BANK_TRANSFER', 'CARD', 'E_WALLET')),
    CONSTRAINT chk_payments_status CHECK (status IN ('PENDING', 'SUCCESS', 'REFUNDED', 'FAILED'))
);

-- Keep existing official databases compatible when this script is executed again.
ALTER TABLE bookings DROP CONSTRAINT IF EXISTS chk_bookings_status;
ALTER TABLE bookings ADD CONSTRAINT chk_bookings_status
    CHECK (status IN ('PENDING', 'PAID', 'REFUND_REQUESTED', 'REFUNDED', 'CANCELLED', 'EXPIRED'));
ALTER TABLE payments DROP CONSTRAINT IF EXISTS chk_payments_status;
ALTER TABLE payments ADD CONSTRAINT chk_payments_status
    CHECK (status IN ('PENDING', 'SUCCESS', 'REFUNDED', 'FAILED'));

CREATE INDEX IF NOT EXISTS idx_flights_route_departure ON flights(departure_airport_id, arrival_airport_id, departure_time);
CREATE INDEX IF NOT EXISTS idx_flights_status ON flights(status);
CREATE INDEX IF NOT EXISTS idx_bookings_customer ON bookings(customer_id, booked_at DESC);
CREATE INDEX IF NOT EXISTS idx_bookings_status ON bookings(status);
CREATE INDEX IF NOT EXISTS idx_booking_passengers_booking ON booking_passengers(booking_id);
CREATE INDEX IF NOT EXISTS idx_payments_booking ON payments(booking_id);
CREATE INDEX IF NOT EXISTS idx_payments_status ON payments(status);

