  AND flights.departure_time = TIMESTAMPTZ '2026-10-12 14:20:00+07'
  AND fare_classes.code = 'ECONOMY'
ON CONFLICT (flight_id, fare_class_id) DO NOTHING;

INSERT INTO flight_fares (flight_id, fare_class_id, price, seat_quota, available_seats)
SELECT flights.id, fare_classes.id, 3650000, 16, 16 FROM flights CROSS JOIN fare_classes
WHERE flights.flight_number = 'QH216'
  AND flights.departure_time = TIMESTAMPTZ '2026-10-12 14:20:00+07'
  AND fare_classes.code = 'BUSINESS'
ON CONFLICT (flight_id, fare_class_id) DO NOTHING;

COMMIT;
